export async function openGoodsReceiptPrint(id: string): Promise<void> {
  const popup = window.open('', '_blank'); const tenantId = getActiveTenantId();
  const response = await fetch(`${API_URL}/goods-receipts/${id}/print`, { credentials: 'include', headers: { Accept: 'text/html', ...(tenantId ? { 'X-Tenant-Id': tenantId } : {}) } });
  if (!response.ok) { popup?.close(); const body = await response.json().catch(() => ({})); throw new ApiError(response.status, body.message ?? `Print failed (${response.status}).`); }
  const url = URL.createObjectURL(await response.blob()); if (popup) popup.location.href = url; else { const link = document.createElement('a'); link.href = url; link.target = '_blank'; link.click(); } window.setTimeout(() => URL.revokeObjectURL(url), 60_000);
}
