export const dispatchPurchaseReturn = (id: string, data: { shipment_date: string; carrier?: string; tracking_reference?: string }) => api<{ data: PurchaseReturn }>(`/purchasing/returns/${id}/dispatch`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
export type PurchasingSetting = { id: string; company_id: string; branch_id?: string | null; default_branch_id?: string | null; default_warehouse_id?: string | null; default_currency_id?: string | null; default_payment_terms?: string | null; default_tax_policy?: string | null; default_po_notes?: string | null; default_delivery_instructions?: string | null; po_expiry_days?: number | null; document_language?: string; receiving_approval_required: boolean; over_receiving_tolerance: string; over_receiving_tolerance_unit: string; partial_receiving_allowed: boolean; quality_inspection_required: boolean; damaged_goods_handling: string; quarantine_required: boolean; batch_tracking_required: boolean; serial_tracking_required: boolean; expiry_validation: boolean; location_validation: boolean; matching_type: string; price_tolerance: string; price_tolerance_unit: string; quantity_tolerance: string; quantity_tolerance_unit: string; tax_tolerance: string; tax_tolerance_unit: string; version: number };
export type PurchasingNumberingPolicy = { id: string; company_id: string; document_type: string; prefix: string; include_year: boolean; include_branch_code: boolean; sequence_length: number; sequence_scope: string; reset_policy: string; next_sequence: number };
export const getPurchasingSettings = (companyId: string) => api<{ data: PurchasingSetting }>(`/purchasing/settings?company_id=${encodeURIComponent(companyId)}`);
export const updatePurchasingSettings = (data: Partial<PurchasingSetting> & { company_id: string }) => api<{ data: PurchasingSetting }>('/purchasing/settings', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
export const getPurchasingNumbering = (companyId: string) => api<{ data: PurchasingNumberingPolicy[] }>(`/purchasing/document-numbering?company_id=${encodeURIComponent(companyId)}`);
export const updatePurchasingNumbering = (data: { company_id: string; document_type: string; prefix: string; include_year: boolean; include_branch_code: boolean; sequence_length: number; sequence_scope: string; reset_policy: string }) => api<{ data: PurchasingNumberingPolicy }>('/purchasing/document-numbering', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
export type PurchasingAutomationRule = { id: string; company_id: string; name: string; rule_type?: string; event_key: string; frequency?: string; timezone?: string; is_active: boolean; conditions?: Record<string, unknown>; actions: Record<string, unknown> };
export const getPurchasingAutomation = (companyId: string) => api<{ data: { data: PurchasingAutomationRule[]; total: number } }>(`/purchasing/automation-rules?company_id=${encodeURIComponent(companyId)}`);
export const createPurchasingAutomation = (data: { company_id: string; name: string; rule_type: string; event_key: string; frequency: string; conditions: Record<string, unknown>; actions: Record<string, unknown>; is_active?: boolean }) => api<{ data: PurchasingAutomationRule }>('/purchasing/automation-rules', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
export const updatePurchasingAutomation = (id: string, data: Partial<PurchasingAutomationRule>) => api<{ data: PurchasingAutomationRule }>(`/purchasing/automation-rules/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
export const dryRunPurchasingAutomation = (id: string) => api<{ data: { would_execute: boolean; matched_records: number; message: string } }>(`/purchasing/automation-rules/${id}/dry-run`, { method: 'POST' });
export const getPurchasingAuditLogs = (companyId: string) => api<{ data: { data: Array<{ id: string; action: string; metadata?: Record<string, unknown>; created_at: string }>; total: number } }>(`/purchasing/audit-logs?company_id=${encodeURIComponent(companyId)}`);
export const getPurchaseRequests = () => api<{ data: { data: Array<{ id: string; number: string; state: string }> } }>('/purchase-requests');
